package money

import (
	"errors"
	"testing"
)

func TestParseMajor(t *testing.T) {
	for _, c := range []struct {
		in   string
		cur  Currency
		want int64
	}{
		{"12.50", USD, 1250},
		{"12.5", USD, 1250},
		{"7", EUR, 700},
		{"0.99", GBP, 99},
		{" 1000.00 ", USD, 100000},
	} {
		got, err := ParseMajor(c.in, c.cur)
		if err != nil || got != c.want {
			t.Errorf("ParseMajor(%q, %s) = %d, %v; want %d", c.in, c.cur, got, err, c.want)
		}
	}
	for _, in := range []string{"", "abc", "-1", "1.", ".5", "1.234", "1,000"} {
		if _, err := ParseMajor(in, USD); !errors.Is(err, ErrInvalidAmount) {
			t.Errorf("ParseMajor(%q) = %v, want ErrInvalidAmount", in, err)
		}
	}
	if _, err := ParseMajor("1", "XYZ"); !errors.Is(err, ErrInvalidAmount) {
		t.Errorf("unknown currency: %v", err)
	}
}

func TestFormat(t *testing.T) {
	for _, c := range []struct {
		amount int64
		cur    Currency
		want   string
	}{
		{1250, USD, "$12.50"},
		{123456789, USD, "$1,234,567.89"},
		{-99, EUR, "-€0.99"},
		{0, GBP, "£0.00"},
		{100000, GBP, "£1,000.00"},
	} {
		if got := Format(c.amount, c.cur); got != c.want {
			t.Errorf("Format(%d, %s) = %q, want %q", c.amount, c.cur, got, c.want)
		}
	}
}

func TestRounding(t *testing.T) {
	for _, c := range []struct {
		amount int64
		pct    int
		want   int64
	}{
		{1000, 15, 150},
		{999, 10, 100}, // 99.9
		{995, 10, 100}, // 99.5 rounds up
		{994, 10, 99},
		{-995, 10, -100}, // half away from zero
	} {
		if got := Percent(c.amount, c.pct); got != c.want {
			t.Errorf("Percent(%d, %d) = %d, want %d", c.amount, c.pct, got, c.want)
		}
	}
	if got := BasisPoints(10000, 825); got != 825 {
		t.Errorf("BasisPoints(10000, 825) = %d", got)
	}
	if got := BasisPoints(1234, 825); got != 102 { // 101.805
		t.Errorf("BasisPoints(1234, 825) = %d", got)
	}
	if got := BasisPoints(200, 2500); got != 50 {
		t.Errorf("BasisPoints(200, 2500) = %d", got)
	}
}
package api

import (
	"errors"
	"fmt"
	"net/http"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// planView is a plan with its price in major units ("12.50") and formatted for people ("$12.50").
type planView struct {
	store.Plan
	Price          string `json:"price"`
	PriceFormatted string `json:"price_formatted"`
}

func viewPlan(p store.Plan) planView {
	return planView{Plan: p, Price: fmt.Sprintf("%.2f", float64(p.UnitAmount)/100), PriceFormatted: money.Format(p.UnitAmount, p.Currency)}
}

func (s *Server) listPlans(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	items := []planView{}
	for _, pl := range s.store.Plans(p.OrgID) {
		items = append(items, viewPlan(pl))
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

// createPlan takes the price in major units, as a string ("12.50"), the way people type it.
func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name      string          `json:"name"`
		Currency  money.Currency  `json:"currency"`
		Price     string          `json:"price"`
		Interval  store.Interval  `json:"interval"`
		UsageType store.UsageType `json:"usage_type"`
		TrialDays int             `json:"trial_days"`
	TotalFormatted string       `json:"total_formatted"`
	Description    string       `json:"description"`
	Customer       *customerRef `json:"customer"`
}

// customerRef is the customer shown on an invoice; null when the customer was deleted.
type customerRef struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

func newInvoiceView(inv store.Invoice, c *store.Customer) invoiceView {
	t := billing.Compute(inv)
	v := invoiceView{Invoice: inv, Totals: t, TotalFormatted: money.Format(t.Total, inv.Currency), Description: describe(inv.Lines)}
	if c != nil {
		v.Customer = &customerRef{ID: c.ID, Name: c.Name, Email: c.Email}
	}
	return v
}

