74	// Format renders an amount for people with the currency's decimals: "$1,234.50", "-€0.99", "¥1,000", "KWD 1.250".
75	func Format(amount int64, c Currency) string {
76		sign, whole, frac := split(amount, c)
77		return sign + symbols[c] + group(whole) + frac
78	}
79	
80	// FormatMajor renders an amount in major units with the currency's decimals and no thousands separator:
81	// "12.50", "1000", "-1.250". It is the form a price takes in the API.
82	func FormatMajor(amount int64, c Currency) string {
83		sign, whole, frac := split(amount, c)
84		return sign + strconv.FormatInt(whole, 10) + frac
85	}
86	
87	// split breaks amount into its sign, its whole major units, and its fraction ("" when the currency has no decimals).
88	func split(amount int64, c Currency) (sign string, whole int64, frac string) {
89		if amount < 0 {
90			sign, amount = "-", -amount
91		}
92		d := c.MinorUnits()
93		scale := int64(1)
94		for range d {
95			scale *= 10
96		}
97		whole, rest := amount/scale, amount%scale
98		if d > 0 {
99			frac = fmt.Sprintf(".%0*d", d, rest)
100		}
101		return sign, whole, frac
102	}
103	
104	// group writes n with a comma between each group of three digits.
105	func group(n int64) string {
106		s := strconv.FormatInt(n, 10)
107		var b strings.Builder
108		for i, r := range s {
109			if i > 0 && (len(s)-i)%3 == 0 {
110				b.WriteByte(',')
111			}
112			b.WriteRune(r)
113		}
114		return b.String()
115	}
116	
117	// Percent returns pct percent of amount, rounded half away from zero to a whole minor unit.
118	func Percent(amount int64, pct int) int64 { return divRound(amount*int64(pct), 100) }
119	
120	// BasisPoints returns bp basis points (hundredths of a percent) of amount, rounded half away from zero.
121	func BasisPoints(amount int64, bp int) int64 { return divRound(amount*int64(bp), 10000) }
122	
123	// divRound divides and rounds half away from zero.
124	func divRound(num, den int64) int64 {
125		if (num < 0) != (den < 0) {
126			return -((abs(num) + abs(den)/2) / abs(den))
127		}
128		return (abs(num) + abs(den)/2) / abs(den)
129	}
130	
131	func abs(v int64) int64 {
132		if v < 0 {
133			return -v
134		}
135		return v
136	}
